const prep = $('Prep SEO Edits').first().json;
const j = $input.first().json;

const decode = s => typeof s === 'string'
  ? s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
     .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&#x2F;/g, '/')
  : s;

const out = { ...prep.prompts };
if (j.translations) {
  prep.fieldNames.forEach((n, i) => { out[n] = decode(j.translations[i].text); });
}

const lockedH1 = prep.lockedH1 || '';
const token = /\{\{\s*LOCKED_H1\s*\}\}/g;

if (token.test(out.applierSystem)) {
  out.applierSystem = out.applierSystem.replace(/\{\{\s*LOCKED_H1\s*\}\}/g, lockedH1);
} else {
  out.applierSystem += `\n\n<locked_h1>\n${lockedH1}\n</locked_h1>\nThe first line of the page is "# " followed by exactly the string above, character for character. If it differs in any way, restore it.`;
}

return [{ json: { ...out, lockedH1 } }];

