={{ (() => {
  const brief = $('Brief EN').first().json;
  const h1 = brief.originalH1 || brief.h1 || '';
  const page = $json.output?.seogoodPage || $('Internal Linker').first().json.output.linksPage || '';
  if (!h1) return page;
  return /^#\s+.+$/m.test(page) ? page.replace(/^#\s+.+$/m, '# ' + h1) : ('# ' + h1 + '\n\n' + page);
})() }}

